import DashboardLayout from "@/components/DashboardLayout";
import { EmptyPanel } from "@/components/campuswear/EmptyPanel";
import { OfflinePanel } from "@/components/campuswear/OfflinePanel";
import { isStalledWithoutData } from "@/lib/queryState";
import { WorkspaceGate } from "@/components/campuswear/WorkspaceGate";
import { Skeleton } from "@/components/ui/skeleton";
import { formatPeso } from "@/lib/format";
import { listVendorInventory, listVendorOrders, vendorInventoryQueryKey, vendorOrdersQueryKey } from "@/lib/supabaseCatalog";
import { useAuth } from "@/_core/hooks/useAuth";
import { useQuery } from "@tanstack/react-query";
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { vendorNavigation, vendorPrimaryAction } from "./workspace";

export default function VendorReports() {
  const { user, loading } = useAuth();
  const orders = useQuery({ queryKey: vendorOrdersQueryKey(user?.id), queryFn: listVendorOrders, enabled: !loading && Boolean(user?.id) });
  const inventory = useQuery({ queryKey: vendorInventoryQueryKey(user?.id), queryFn: listVendorInventory, enabled: !loading && Boolean(user?.id) });
  const report = orders.data ? ["pending", "confirmed", "preparing", "ready_for_pickup", "completed", "cancelled", "rejected"].map(status => ({ status: status.replaceAll("_", " "), count: orders.data.filter(order => order.status === status).length })) : [];
  const completedSales = orders.data?.filter(order => order.status === "completed").reduce((sum, order) => sum + order.totalInCentavos, 0) ?? 0;
  return <DashboardLayout items={vendorNavigation} primaryAction={vendorPrimaryAction} workspaceLabel="Vendor workspace"><WorkspaceGate allowedRoles={["vendor_staff", "platform_admin", "admin"]}><div className="mx-auto max-w-7xl"><p className="text-xs font-bold tracking-[0.12em] text-primary">OPERATIONS REPORT</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-0.055em]">Reports</h1><p className="mt-2 text-sm text-muted-foreground">Every metric below is derived from your current CampusWear orders and inventory.</p>{orders.isLoading || inventory.isLoading ? <div className="mt-7 grid gap-4 lg:grid-cols-2"><Skeleton className="h-72 rounded-2xl" /><Skeleton className="h-72 rounded-2xl" /></div> : isStalledWithoutData(orders) || isStalledWithoutData(inventory) ? <div className="mt-7"><OfflinePanel title="You are offline" detail="Reconnect to rebuild your operational report." onRetry={() => { orders.refetch(); inventory.refetch(); }} /></div> : orders.isError || inventory.isError ? <div className="mt-7"><EmptyPanel title="Report data is unavailable" detail="Please refresh the workspace to load your operational summary." action={{ label: "Try again", onClick: () => { orders.refetch(); inventory.refetch(); } }} /></div> : <><div className="mt-7 grid gap-4 sm:grid-cols-3"><article className="rounded-2xl border border-border bg-card p-5"><p className="text-2xl font-extrabold tracking-[-0.05em]">{orders.data?.length ?? 0}</p><p className="mt-1 text-sm font-semibold text-muted-foreground">Total orders</p></article><article className="rounded-2xl border border-border bg-card p-5"><p className="text-2xl font-extrabold tracking-[-0.05em] text-primary">{formatPeso(completedSales)}</p><p className="mt-1 text-sm font-semibold text-muted-foreground">Completed order sales</p></article><article className="rounded-2xl border border-border bg-card p-5"><p className="text-2xl font-extrabold tracking-[-0.05em] text-amber-700">{inventory.data?.filter(item => item.availability !== "in_stock").length ?? 0}</p><p className="mt-1 text-sm font-semibold text-muted-foreground">Low or out of stock sizes</p></article></div><section className="mt-7 h-[330px] rounded-2xl border border-border bg-card p-5"><h2 className="font-extrabold">Order pipeline</h2><p className="mt-1 text-xs text-muted-foreground">Current order counts by lifecycle state.</p><div className="mt-5 h-[240px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={report}><XAxis dataKey="status" tick={{ fontSize: 11 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fontSize: 11 }} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: "#f1f5f9" }} /><Bar dataKey="count" fill="#315985" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></div></section></>}</div></WorkspaceGate></DashboardLayout>;
}
